		StringBuilder msg = new StringBuilder( "-- Failed to get all Case_ : " );        
		List<Case_> collection  = new ArrayList<>();

		try {
			// call the static get method on the Case_Service
			collection = Case_Service.getCase_Instance().getAllCase_();
			assertNotNull( collection, "An Empty collection of Case_ was incorrectly returned.");
			
			// Now print out the values
			Case_ entity = null;            
			Iterator<Case_> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getCase_Id(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
